<?php
namespace App\\Models;use Illuminate\\Database\\Eloquent\\Model;use Illuminate\\Database\\Eloquent\\Relations\\{BelongsTo,HasMany,HasOne};class Order extends Model{protected $fillable=['user_id','number','currency','subtotal','shipping_fee','total','status','payment_status','payment_method','shipping_name','shipping_phone','shipping_address','shipping_city','notes'];protected function casts():array{return ['subtotal'=>'decimal:2','shipping_fee'=>'decimal:2','total'=>'decimal:2'];}public function user():BelongsTo{return $this->belongsTo(User::class);}public function items():HasMany{return $this->hasMany(OrderItem::class);}public function payment():HasOne{return $this->hasOne(Payment::class);}}
